const float PI = 3.14159265;

float angular_difference(float a, float b) {
    float diff = a - b;
    return mod(diff + PI, 2.0 * PI) - PI;
}

float rand(vec2 co){
    return fract(sin(dot(co, vec2(12.9898, 78.233))) * 43758.5453);
}

vec2 rand2(vec2 co) {
    return vec2(rand(co), rand(co + 1.0));
}

float shadow(vec2 uv, vec2 p1, vec2 p2, vec2 o1, vec2 o2) {
    float t1 = ((p1.y - o2.y) * (uv.x - o2.x) - (p1.x - o2.x) * (uv.y - o2.y)) 
             / ((p2.x - p1.x) * (uv.y - o2.y) - (p2.y - p1.y) * (uv.x - o2.x));

    float t2 = ((p2.y - o1.y) * (uv.x - o1.x) - (p2.x - o1.x) * (uv.y - o1.y)) 
             / ((p1.x - p2.x) * (uv.y - o1.y) - (p1.y - p2.y) * (uv.x - o1.x));

    float i1 = smoothstep(0.0, 1.0, t1);
    float i2 = smoothstep(0.0, 1.0, t2);

    float l = (i1 + i2) / 2.0;

    if (uv.y > min(o1.y, o2.y) && uv.y < max(o1.y, o2.y)) l = 1.0 - abs(0.5 - l);
    l -= 0.5;
    l *= 2.0;

    float pm = (o1.y - o2.y) / (o1.x - o2.x);
    float pb = o1.y - pm * o1.x;
    float p = pm * uv.x + pb;

    if (uv.y > p) {
        return 0.0;
    }

    return abs(l);
}

float beam(vec2 uv, vec2 p1, vec2 p2) {
    // Compute vectors from UV to c1 and c2
    vec2 v1 = p1 - uv;
    vec2 v2 = p2 - uv;

    // Calculate angle between v1 and v2 using atan2 of cross and dot products
    float a1 = atan(v1.y, v1.x);
    float a2 = atan(v2.y, v2.x);
    float angle_diff = angular_difference(a1, a2);

    // Compute luminance
    float lum = angle_diff / PI;

    return lum * abs(lum);
}

vec3 aces_approx(vec3 v)
{
    v *= 0.6f;
    float a = 2.51f;
    float b = 0.03f;
    float c = 2.43f;
    float d = 0.59f;
    float e = 0.14f;
    return clamp((v*(a*v+b))/(v*(c*v+d)+e), 0.0f, 1.0f);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalize and center UV coordinates
    vec2 uv = (fragCoord.xy / iResolution.xy - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);

    vec2 p1 = vec2(-0.2, 0.2);
    vec2 p2 = vec2(0.2, 0.2);

    vec2 o1 = vec2(0.2 - cos(iTime) / 10.0, 0.0 + sin(iTime) / 10.0);
    vec2 o2 = vec2(-0.2 + cos(iTime) / 10.0, 0.0 + sin(iTime) / 10.0);

    float acc = 0.0;
    acc += beam(uv, p1, p2) * 2.5;

    acc = max(acc, 0.0);

    acc = mix(acc, 0.0, shadow(uv, p1, p2, o1, o2));

    // Output to screen with proper alpha channel
    fragColor = vec4(pow(aces_approx(vec3(acc) * vec3(1, 0.75, 0.5)), vec3(1.0 / 2.2)), 1.0);
}
